rules.logic:
// --- Idempotency guard ---
if (element.querySelector('#recommended-self-help-block')) return;

// --- Collect links from sidebar ---
const sidebarLinks = [];
document.querySelectorAll('.collapsible-sidebar-body a.sidenav-item').forEach(a => {
  if (!a.classList.contains('current-article')) {
    sidebarLinks.push({ href: a.href, text: a.textContent.trim() });
  }
});

// --- Collect links from related articles ---
const relatedLinks = [];
document.querySelectorAll('.related-articles ul li a').forEach(a => {
  relatedLinks.push({ href: a.href, text: a.textContent.trim() });
});

// --- Merge, deduplicate by text ---
const seen = new Set();
const allLinks = [];
[...sidebarLinks, ...relatedLinks].forEach(link => {
  if (!seen.has(link.text)) {
    seen.add(link.text);
    allLinks.push(link);
  }
});

if (allLinks.length === 0) return;

// --- Build the block ---
const block = document.createElement('div');
block.id = 'recommended-self-help-block';
block.style.cssText = [
  'margin: 0 0 28px 0',
  'padding: 20px 24px 18px 24px',
  'background: linear-gradient(135deg, #f0f7ff 0%, #e8f4e8 100%)',
  'border: 2px solid #4a90d9',
  'border-radius: 10px',
  'box-shadow: 0 3px 12px rgba(74,144,217,0.15)',
  'font-family: inherit'
].join(';');

// Header row
const header = document.createElement('div');
header.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:14px;';

const icon = document.createElement('span');
icon.textContent = '💡';
icon.style.cssText = 'font-size:22px;line-height:1;';

const title = document.createElement('h2');
title.textContent = 'Recommended Self-Help';
title.style.cssText = [
  'margin: 0',
  'font-size: 16px',
  'font-weight: 700',
  'color: #1a3a5c',
  'letter-spacing: 0.3px',
  'text-transform: uppercase'
].join(';');

const badge = document.createElement('span');
badge.textContent = allLinks.length + ' articles';
badge.style.cssText = [
  'margin-left: auto',
  'background: #4a90d9',
  'color: #fff',
  'font-size: 11px',
  'font-weight: 600',
  'padding: 2px 9px',
  'border-radius: 20px',
  'letter-spacing: 0.5px'
].join(';');

header.appendChild(icon);
header.appendChild(title);
header.appendChild(badge);
block.appendChild(header);

// Divider
const divider = document.createElement('hr');
divider.style.cssText = 'border:none;border-top:1px solid #c5ddf5;margin:0 0 14px 0;';
block.appendChild(divider);

// Links grid
const grid = document.createElement('ul');
grid.style.cssText = [
  'list-style: none',
  'margin: 0',
  'padding: 0',
  'display: grid',
  'grid-template-columns: repeat(auto-fill, minmax(230px, 1fr))',
  'gap: 8px 16px'
].join(';');

allLinks.forEach(link => {
  const li = document.createElement('li');
  li.style.cssText = 'display:flex;align-items:flex-start;gap:7px;';

  const bullet = document.createElement('span');
  bullet.textContent = '→';
  bullet.style.cssText = 'color:#4a90d9;font-weight:700;font-size:14px;margin-top:1px;flex-shrink:0;';

  const a = document.createElement('a');
  a.href = link.href;
  a.textContent = link.text;
  a.style.cssText = [
    'color: #1a5fa8',
    'font-size: 14px',
    'font-weight: 500',
    'text-decoration: none',
    'line-height: 1.4',
    'transition: color 0.15s'
  ].join(';');
  a.addEventListener('mouseover', () => { a.style.color = '#e85d04'; a.style.textDecoration = 'underline'; });
  a.addEventListener('mouseout', () => { a.style.color = '#1a5fa8'; a.style.textDecoration = 'none'; });

  li.appendChild(bullet);
  li.appendChild(a);
  grid.appendChild(li);
});

block.appendChild(grid);

// --- Insert after article header ---
const articleHeader = element.querySelector('header.article-header');
if (articleHeader && articleHeader.nextSibling) {
  element.insertBefore(block, articleHeader.nextSibling);
} else if (articleHeader) {
  element.appendChild(block);
}

// --- Hide original sources ---
const sidebar = document.querySelector('.article-sidebar');
if (sidebar) sidebar.style.display = 'none';

const relatedSection = document.querySelector('.article-relatives');
if (relatedSection) relatedSection.style.display = 'none';
